entries[163573] = { ["name"] = "Goldenmane's Reins", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon Goldenmane.\nSummons and dismisses Goldenmane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Lord Stormsong ordered his cronies to steal this horse from the Norwington Estate in Tiragarde, as he was covetous of its luscious golden mane.\"\nZone:\nStormsong" }
entries[163574] = { ["name"] = "Chewed-On Reins of the Terrified Pack Mule", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Terrified Pack Mule.\nSummons and dismisses your Terrified Pack Mule.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"This poor mule was around Drustvar when the witches took over. He's seen too much.\"\nZone:\nDrustvar" }
entries[163575] = { ["name"] = "Reins of a Tamed Bloodfeaster", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Leaping Veinseeker.\nSummons and dismisses your Leaping Veinseeker.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Bug spray and a hat with netting aren't going to do much in the swamps of Nazmir, bring a club.\"\nZone:\nNazmir" }
entries[163576] = { ["name"] = "Captured Dune Scavenger", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Dune Scavenger.\nSummons and dismisses your Dune Scavenger.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These resilient scavengers can survive for months in the wastes of Vol'dun with scarce access to food and water.\"\nZone:\nVol'dun" }
entries[163577] = { ["name"] = "Conqueror's Scythemaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Conqueror's Scythemaw.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The battle-hardened shell of this mighty beast can turn aside even the most hefty hammer or sharpened spear.\"\nAchievement:\nConqueror of Azeroth\nCategory:\nWorld" }
entries[163578] = { ["name"] = "Broken Highland Mustang", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Broken Highland Mustang.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"One of the Arathi horses, taken and broken by the Horde conquerors of Stromgarde.\"\nDrop:\nKnight-Captain Aldrin\nZone:\nArathi Highlands" }
entries[163579] = { ["name"] = "Highland Mustang", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Highland Mustang.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A valiant steed on the Arathi Highlands, it knows no fear.\"\nDrop:\nDoomrider Helgrim\nZone:\nArathi Highlands" }
