entries[163582] = { ["name"] = "Qinsho's Eternal Hound", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses Qinsho's Eternal Hound.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Qinsho wrought his eternal guardian from pure gold and imbued it with the resilience of the earth.\"\nDrop:\nIsland Expeditions" }
entries[163583] = { ["name"] = "Craghorn Chasm-Leaper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Craghorn Chasm-Leaper.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These mighty leapers have adapted to island life by learning to catch seagulls swooping through crags and fissures.\"\nDrop:\nIsland Expeditions" }
entries[163584] = { ["name"] = "Twilight Avenger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Little is known about the fate of the twilight dragonflight, though they seem to exist in numbers in Grim Batol to this day.\"\nDrop:\nIsland Expeditions" }
entries[163585] = { ["name"] = "Surf Jelly", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The time between being stung and being enveloped and devoured is short enough to consider not swimming in the Great Sea.\"\nDrop:\nIsland Expeditions" }
entries[163586] = { ["name"] = "Squawks", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses Squawks. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Guess why he's called that? It's not because he's a nice, quiet pet.\"\nDrop:\nIsland Expeditions" }
