entries[163714] = { ["name"] = "Forbidden Sea Shanty of the Lively Men", ["text"] = "Binds when picked up\n\"The lyrics encourage the men to cheer up and act lively, but it is clear none of them are still alive.\"\nSell Price:" }
entries[163715] = { ["name"] = "Forbidden Sea Shanty of Fruit Counting", ["text"] = "Binds when picked up\n\"At first it appears to be a simple dock worker's song, but it occurs to you the worker is Death, collecting souls while wishing for the end of its own existence.\"\nSell Price:" }
entries[163716] = { ["name"] = "Forbidden Sea Shanty of Inebriation", ["text"] = "Binds when picked up\n\"At first glance, the shanty lyrics describe a crew playing some merry pranks on an inebriated crewmember. The more you think about the lyrics, the more disturbing it becomes.\"\nSell Price:" }
entries[163717] = { ["name"] = "Forbidden Sea Shanty of Josephus", ["text"] = "Binds when picked up\n\"The lyrics of this shanty detail the disgusting port-town exploits of a sailor apparently known as \"Joe\".\"\nSell Price:" }
entries[163718] = { ["name"] = "Forbidden Sea Shanty of the Black Sphere", ["text"] = "Binds when picked up\n\"The lyrics of this shanty describe sailors' cruel treatment at the hands of a captain known as Blackball Bill.\"\nSell Price:" }
